First - thank you for your work on mailgen. It's amazing. This is a very small tweak allowing me to use my own theme.

BTW - this is how i end up defining my theme. 

```rust
use minijinja::Environment;
use serde::Serialize;

pub use crate::utils::Result;
use crate::utils::{Context, MyError};
use mailgen::{TemplateContext, Theme};

static HTML: &str = include_str!("template.html");
static TEXT: &str = include_str!("template.text");

#[derive(Serialize)]
struct GolfThemeContext<'a> {
    #[serde(flatten)]
    context: &'a TemplateContext<'a>,

    logo_max_height: u32,
}

#[derive(Debug, Clone)]
pub struct GolfTheme {
    environment: Environment<'static>,

    pub logo_max_height: u32,
}

impl GolfTheme {
    pub fn new() -> Result<Self> {
        let mut environment = Environment::new();
        environment
            .add_template("html", HTML)
            .context("Failed to add HTML template")?;
        environment
            .add_template("text", TEXT)
            .context("Failed to add TEXT template")?;

        Ok(Self {
            environment,

            logo_max_height: 50,
        })
    }

    fn render(&self, template: &str, context: &TemplateContext) -> Result<String> {
        let context = GolfThemeContext {
            context,

            logo_max_height: self.logo_max_height,
        };

        let template = self
            .environment
            .get_template(template)
            .context(format!("Failed to get template: {}", template))?;
        let rendered = template
            .render(context)
            .context("Failed to render template")?;
        Ok(rendered)
    }
}

impl Theme for GolfTheme {
    type Error = MyError;

    fn html(&self, context: &TemplateContext) -> std::result::Result<String, Self::Error> {
        let html = self
            .render("html", context)
            .context("Failed to render HTML template")?;
        let html = css_inline::inline(&html).context("Failed to inline CSS")?;

        Ok(html)
    }

    fn text(&self, context: &TemplateContext) -> std::result::Result<String, Self::Error> {
        let text = self
            .render("text", context)
            .context("Failed to render text template")?;
        let text =
            html2text::from_read(text.as_bytes(), 80).context("Failed to convert HTML to text")?;

        Ok(text)
    }
}
```

